import Foundation
import XCTest
@testable import MacScope

/// Base-ISA decoder coverage against the Apple oracle (replaces ARM64CoverageHarnessTests, which
/// decoded /usr/lib/dyld on every run and counted any non-`unknown` mnemonic, fabricated or not, as
/// success). `GoldenFixtures/arm64-coverage-vectors/vectors.tsv` is generated by
/// `Scripts/arm64_golden/generate_arm64_coverage_vectors.py`: structured words for every base-ISA
/// encoding class, labelled by Apple clang 21 + `llvm-objdump` in generic syntax. Where objdump
/// rejects a word MacScope must print `unknown`; where it decodes the word MacScope must print the
/// same text, except for the MS-23 ledger §6 gaps and the spelling-only differences named below.
final class ARM64OracleCoverageGoldenTests: XCTestCase {
    private struct Row {
        let family: String
        let address: UInt64
        let word: UInt32
        let objdump: String
    }

    private static let fixture = TestSourceRoot.fileURL(#filePath)
        .deletingLastPathComponent()
        .appendingPathComponent("GoldenFixtures/arm64-coverage-vectors/vectors.tsv")

    private static func rows() throws -> [Row] {
        let text = try String(contentsOf: fixture, encoding: .utf8)
        return try text.split(separator: "\n", omittingEmptySubsequences: true)
            .filter { !$0.hasPrefix("#") }
            .map { line in
                let fields = line.components(separatedBy: "\t")
                XCTAssertEqual(fields.count, 4, "malformed row \(line)")
                return Row(
                    family: fields[0],
                    address: try XCTUnwrap(UInt64(fields[1].dropFirst(2), radix: 16)),
                    word: try XCTUnwrap(UInt32(fields[2], radix: 16)),
                    objdump: fields[3]
                )
            }
    }

    /// Base-ISA forms MacScope leaves `unknown` on purpose or as tracked gaps (MS-23 ledger §6).
    private static func isAcceptedGap(_ objdump: String, word: UInt32) -> Bool {
        let mnemonic = objdump.split(separator: " ", maxSplits: 1).first.map(String.init) ?? ""
        let operands = objdump.dropFirst(mnemonic.count).trimmingCharacters(in: .whitespaces)
        // Implementation-defined system registers and SYS/SYSL operations (policy).
        if mnemonic == "sys" || mnemonic == "sysl" { return true }
        if (mnemonic == "msr" || mnemonic == "mrs"), objdump.contains("s0_") { return true }
        // Exclusive and ordered loads/stores whose should-be-one Rs/Rt2 fields are not all ones:
        // CONSTRAINED UNPREDICTABLE, which MacScope rejects by design.
        if (word & 0x3f00_0000) == 0x0800_0000 {
            let rsNotOnes = (word >> 16) & 0x1f != 0x1f, rt2NotOnes = (word >> 10) & 0x1f != 0x1f
            switch ((word >> 23) & 1, (word >> 22) & 1, (word >> 21) & 1) {
            case (0, 1, 1): return rsNotOnes                // ldxp/ldaxp
            case (_, 1, 0): return rsNotOnes || rt2NotOnes  // ldxr/ldaxr/ldar/ldlar
            case (0, 0, 0): return rt2NotOnes               // stxr/stlxr
            case (1, 0, 0): return rsNotOnes || rt2NotOnes  // stlr/stllr
            default: return false
            }
        }
        // MTE ADDG/SUBG with the should-be-zero bits 15:14 set (policy).
        if (mnemonic == "addg" || mnemonic == "subg"), (word >> 14) & 3 != 0 { return true }
        // Unprivileged LDTR*/STTR* (ledger §6 groups them with the out-of-scope ldt*/stt* family).
        if mnemonic.hasPrefix("ldtr") || mnemonic.hasPrefix("sttr") { return true }
        // Advanced SIMD vector forms the ledger lists as a separate decoder-coverage item.
        if operands.hasPrefix("v"), simdCoverageGaps.contains(mnemonic) { return true }
        return false
    }

    private static let simdCoverageGaps: Set<String> = [
        "uqshl", "sqshl", "urshl", "sqrshl", "uqrshl", "srshl", "ushl", "sshl", "urhadd", "srhadd", "uqadd",
        "sqadd", "uqsub", "sqsub", "shsub", "uhsub", "shadd", "uhadd", "mla", "mls", "sabd", "uabd", "saba", "uaba",
        "usra", "ssra", "ursra", "srsra", "sqshlu", "scvtf", "ucvtf", "fcvtzs", "fcvtzu", "sabdl", "sabdl2", "uabdl",
        "uabdl2", "rsubhn", "rsubhn2", "raddhn", "raddhn2", "subhn", "subhn2", "addhn", "addhn2", "umull", "umull2",
        "smull", "smull2", "usubl", "usubl2", "ssubl", "ssubl2", "uaddl", "uaddl2", "saddl", "saddl2", "usubw",
        "usubw2", "ssubw", "ssubw2", "uaddw", "uaddw2", "saddw", "saddw2", "umlal", "umlal2", "smlal", "smlal2",
        "umlsl", "umlsl2", "smlsl", "smlsl2", "sabal", "sabal2", "uabal", "uabal2", "pmull", "pmull2",
    ]

    private func decode(_ word: UInt32, at address: UInt64) -> DecodedInstruction {
        let data = Data([
            UInt8(word & 0xff), UInt8((word >> 8) & 0xff), UInt8((word >> 16) & 0xff), UInt8((word >> 24) & 0xff),
        ])
        return ARM64Decoder().decode(data, baseAddress: address, maxInstructionCount: 1)[0]
    }

    /// Spelling-only normalisation (MS-23 ledger §5): lower case, `{ v0 }` → `{v0}`, every number by
    /// value, `#imm, lsl #12` folded into one immediate, a zero shift dropped, and MOV immediates
    /// compared modulo the register width (LLVM prints `mov w0, #-0x1`, MacScope `#0xffffffff`).
    static func normalized(_ text: String) -> String {
        var result = text.lowercased().replacingOccurrences(of: "{ ", with: "{").replacingOccurrences(of: " }", with: "}")
        result = result.split(separator: " ", omittingEmptySubsequences: true).joined(separator: " ")
        result = result.replacingOccurrences(of: #", (lsl|lsr|asr|ror) #(0x)?0$"#, with: "", options: .regularExpression)
        if let match = result.range(of: #"#(0x[0-9a-f]+|[0-9]+), lsl #12$"#, options: .regularExpression) {
            let token = result[match].dropFirst().split(separator: ",")[0]
            let value = token.hasPrefix("0x") ? UInt64(token.dropFirst(2), radix: 16) : UInt64(token)
            if let value { result.replaceSubrange(match, with: "#\(value << 12)") }
        }
        let pattern = try! NSRegularExpression(pattern: #"(?<![A-Za-z0-9_])(-?)(0x[0-9a-fA-F]+|[0-9]+)(?![A-Za-z0-9_])"#)
        let source = result
        for match in pattern.matches(in: source, range: NSRange(source.startIndex..., in: source)).reversed() {
            guard let whole = Range(match.range, in: result),
                  let sign = Range(match.range(at: 1), in: source),
                  let digits = Range(match.range(at: 2), in: source) else { continue }
            let token = String(source[digits])
            guard let value = token.hasPrefix("0x") ? UInt64(token.dropFirst(2), radix: 16) : UInt64(token) else { continue }
            if source.hasPrefix("mov ") {
                let negative = !source[sign].isEmpty
                var bits = negative ? (0 &- value) : value
                if source.hasPrefix("mov w") { bits &= 0xffff_ffff }
                result.replaceSubrange(whole, with: "\(bits)")
            } else {
                result.replaceSubrange(whole, with: "\(source[sign])\(value)")
            }
        }
        return result
    }

    /// Named system registers and prefetch operations that MacScope spells generically (ledger §5,
    /// cosmetic). The generic spelling is accepted only when it is exactly the word's own fields.
    private static func isGenericSpelling(of objdump: String, macScope: String, word: UInt32) -> Bool {
        let mnemonic = objdump.split(separator: " ").first.map(String.init) ?? ""
        if mnemonic == "mrs" || mnemonic == "msr" {
            let op0 = 2 + ((word >> 19) & 1), op1 = (word >> 16) & 7, crn = (word >> 12) & 0xf
            let crm = (word >> 8) & 0xf, op2 = (word >> 5) & 7
            let generic = "s\(op0)_\(op1)_c\(crn)_c\(crm)_\(op2)"
            let xt = (word & 0x1f) == 31 ? "xzr" : "x\(word & 0x1f)"
            return macScope == (mnemonic == "mrs" ? "mrs \(xt), \(generic)" : "msr \(generic), \(xt)")
        }
        if mnemonic == "prfm" || mnemonic == "prfum" {
            let named = objdump.split(separator: " ", maxSplits: 2)
            let generic = macScope.split(separator: " ", maxSplits: 2)
            guard named.count == 3, generic.count == 3, generic[0] == named[0] else { return false }
            return generic[1] == "#\(word & 0x1f)," && normalized(String(generic[2])) == normalized(String(named[2]))
        }
        return false
    }

    func testBaseISAWordsMatchAppleTextOrDecodeAsUnknown() throws {
        let rows = try Self.rows()
        XCTAssertGreaterThan(rows.count, 1500)
        var rejected = 0, exact = 0, gaps = 0
        for row in rows {
            let decoded = decode(row.word, at: row.address)
            let text = decoded.operands.isEmpty ? decoded.mnemonic : "\(decoded.mnemonic) \(decoded.operands)"
            let context = "\(row.family) \(String(format: "%08x", row.word)): objdump `\(row.objdump)`, MacScope `\(text)`"
            if row.objdump == "<unknown>" {
                XCTAssertEqual(decoded.mnemonic, "unknown", context)
                rejected += 1
            } else if decoded.mnemonic == "unknown" {
                XCTAssertTrue(Self.isAcceptedGap(row.objdump, word: row.word), "unexpected gap: \(context)")
                gaps += 1
            } else if !Self.isGenericSpelling(of: row.objdump, macScope: text, word: row.word) {
                XCTAssertEqual(Self.normalized(text), Self.normalized(row.objdump), context)
                exact += 1
            }
        }
        XCTAssertGreaterThan(rejected, 900)
        XCTAssertGreaterThan(exact, 700)
        XCTAssertLessThan(gaps, 80)
    }
}
